async function(name,args,label,weightOverride){
 const Policy=eval("("+load("rateClass")+")"); const s=load("rateState");const weight=weightOverride??args.actions?.length??1;
 if(s.rateErrors>=4)throw Error("STOP_AFTER_RETRIES");
 let wait=Policy.waitMs(s,weight,Date.now());
 while(wait>0){s.log.push({type:"pause",label,at:new Date().toISOString(),waitMs:wait});store("rateState",s);if(wait>5000)notify("Контроль темпу: пауза "+Math.ceil(wait/1000)+" с.");await new Promise(r=>setTimeout(r,Math.min(wait,45000)));wait=Policy.waitMs(s,weight,Date.now());}
 const start=Date.now();let result;
 try{result=await tools[name](args);}catch(e){result={isError:true,exception:String(e)};}
 const end=Date.now();Policy.finish(s,weight,end);
 const info=Policy.responseInfo(result),is429=info.is429;
 if(info.limit && info.limit<s.budget)s.budget=info.limit;
 if(is429){const retry=Policy.rateLimited(s,info.retryAfter,end);s.log.push({type:"rate_limit",at:new Date(end).toISOString(),...retry});}
 s.log.push({type:"call",label,tool:name,startedAt:new Date(start).toISOString(),endedAt:new Date(end).toISOString(),weight,is429,isError:!!result.isError,...(info.limit?{serverLimit:info.limit,serverRemaining:info.remaining}:{})});
 store("rateState",s);store(label,result);store("lastResult",result);
 if(is429){await eval("("+load("persist")+")")("execution-state.json",{phase:"429_cooldown_reconcile_required",rate:s,appliedBatches:load("appliedBatches")});throw Error("RATE_LIMIT_RECONCILE_REQUIRED");}
 return result;
}

