async function(batch){
 const call=eval("("+load("limited")+")"),persist=eval("("+load("persist")+")");
 const scope=batch.ops[0].scope_component_id;
 if(!batch.ops.every(x=>x.scope_component_id===scope)) throw Error("Mixed scope");
 const get=async label=>{
  const r=await call("mcp__webflow__data_element_tool",{siteId:load("plan").target.site_id,pageId:load("plan").target.page_id,actions:[{label,get_all_elements:{depth:-1,...(scope?{scope_component_id:scope}:{})}}]},label);
  const parsed=r.content.filter(x=>x.type==="text").map(x=>JSON.parse(x.text));
  const result=parsed[0]?.result?.[0];if(result?.status!=="success")throw Error("Read failed "+JSON.stringify(r).slice(0,1000));
  return result.data;
 };
 const before=await get("guard-"+batch.label);
 const flat=eval("("+load("flatten")+")")(before), map=new Map(flat.map(n=>[n.id.element,n]));
 const status=batch.ops.map(op=>{
 const actual=map.get(op.id.element)?.textContent;return{...op,actual,status:actual===op.approved_new_raw?"already_applied":actual===op.expected_current_raw?"eligible":"conflict"};});
 if(status.some(x=>x.status==="conflict")){await persist("conflict-"+batch.label+".json",status);throw Error("Conflict "+batch.label);}
 const pending=status.filter(x=>x.status==="eligible");
 if(pending.length){
  const r=await call("mcp__webflow__data_element_tool",{siteId:load("plan").target.site_id,pageId:load("plan").target.page_id,actions:pending.map(op=>({label:op.label,set_text:{id:op.id,text:op.approved_new_raw,...(scope?{scope_component_id:scope}:{})}}))},"write-"+batch.label);
  await persist("write-"+batch.label+".json",r);
 }
 const after=await get("readback-"+batch.label);
 const mapAfter=new Map(eval("("+load("flatten")+")")(after).map(n=>[n.id.element,n]));
 const checks=batch.ops.map(op=>({label:op.label,field_id:op.field_id,id:op.id,before:map.get(op.id.element)?.textContent,approved:op.approved_new_raw,actual:mapAfter.get(op.id.element)?.textContent,verified:mapAfter.get(op.id.element)?.textContent===op.approved_new_raw}));
 await persist("readback-"+batch.label+".json",{checks,tree:after});
 store("lastTree:"+ (scope??load("plan").target.page_id),after);
 const done=load("appliedBatches")??[];done.push({label:batch.label,at:new Date().toISOString(),ops:checks.length,verified:checks.every(x=>x.verified)});store("appliedBatches",done);
 await persist("execution-state.json",{phase:"applying_text",rate:load("rateState"),appliedBatches:done});
 if(checks.some(x=>!x.verified))throw Error("Partial/unknown "+batch.label);
 text({batch:batch.label,verified:checks.length,totalVerified:done.reduce((n,x)=>n+x.ops,0)});
}

rateClass:
class WebflowRatePolicy {
  static responseInfo(response) {
    // MCP can return an HTTP failure inside a text block without isError.
    const raw = JSON.stringify(response);
    const is429 = /Too Many Requests|too_many_requests|RATE_LIMITED|returned\s*429|status.{0,12}429|rate.limit.exceeded/i.test(raw);
    const headers = {};
    const visit = value => {
      if (!value || typeof value !== 'object') return;
      for (const [key, child] of Object.entries(value)) {
        const name = key.toLowerCase();
        if (['retry-after', 'x-ratelimit-limit', 'x-ratelimit-remaining'].includes(name)) headers[name] = child;
        if (key === 'text' && typeof child === 'string') {
          try { visit(JSON.parse(child)); } catch { /* Plain diagnostic text. */ }
        } else visit(child);
      }
    };
    visit(response);
    return {is429, retryAfter:headers['retry-after'], limit:Number(headers['x-ratelimit-limit']) || null, remaining:headers['x-ratelimit-remaining'] ?? null};
  }
  static waitMs(s, weight, now) {
    if (!Number.isInteger(weight) || weight < 1 || weight > 10) throw new Error('Batch must have 1..10 operations');
    s.events = s.events.filter(e => now - e.at < 60000);
    let wait = Math.max(0, s.lastEnd + 2000 - now, s.cooldownUntil - now);
    let used = s.events.reduce((n,e) => n + e.weight, 0);
    if (used + weight > s.budget) {
      for (const e of [...s.events].sort((a,b)=>a.at-b.at)) {
        used -= e.weight;
        wait = Math.max(wait, e.at + 60000 - now);
        if (used + weight <= s.budget) break;
      }
    }
    return wait;
  }
  static finish(s, weight, now) { s.events.push({at:now,weight}); s.lastEnd=now; }
  static rateLimited(s, retryAfter, now) {
    s.rateErrors += 1; s.budget = Math.min(s.budget,15);
    let ms = Number(retryAfter) * 1000;
    if (!Number.isFinite(ms) || ms <= 0) ms = Date.parse(retryAfter) - now;
    if (!Number.isFinite(ms) || ms <= 0) ms = 60000 * 2 ** Math.min(s.rateErrors-1,2);
    s.cooldownUntil = now + ms + 2000;
    return {waitMs:ms+2000,stop:s.rateErrors>=4};
  }
  static reconcile(expected, actual) {
    return expected.map(e=>({id:e.id,status:actual[e.id]===e.after?'applied':actual[e.id]===e.before?'retry':'conflict'}));
  }
}
